const item = $input.first().json;
let chatId, text, username;
if (item.message) {
  chatId = String(item.message.chat.id);
  text = String(item.message.text || '').trim();
  username = item.message.from.first_name || '';
} else if (item.callback_query) {
  chatId = String(item.callback_query.message.chat.id);
  text = String(item.callback_query.data || '').trim();
  username = item.callback_query.from.first_name || '';
} else {
  return [];
}
return [{ json: { chatId, text, username } }];

const norm = $('Normalizar Entrada').first().json;
const sesItems = $input.all();
let sesion = { telegram_id: norm.chatId, paso: '', datos: '{}', id_estudiante: '' };
if (sesItems.length > 0 && sesItems[0].json && sesItems[0].json.telegram_id) {
  sesion = sesItems[0].json;
}
let datos = {};
try { datos = JSON.parse(sesion.datos || '{}'); } catch (e) { datos = {}; }
return [{ json: { chatId: norm.chatId, text: norm.text, username: norm.username, paso: sesion.paso || '', datos, id_estudiante: sesion.id_estudiante || '' } }];

const s = $('Cargar Sesion').first().json;
const chatId = s.chatId;
let text = s.text;
let paso = s.paso || '';
let datos = s.datos || {};

const estudiantes = $('Leer Estudiantes').all().map(i => i.json);
const tutores = $('Leer Tutores').all().map(i => i.json);
const materiasRows = $('Leer Materias').all().map(i => i.json);
const materiaNombre = m => m.nombre || m.nombre_materia || m.materia || '';
const materias = materiasRows.map(materiaNombre).filter(Boolean);
const materiaNombrePorId = id => { const m = materiasRows.find(x => String(x.id_materia) === String(id)); return m ? materiaNombre(m) : String(id); };
const materiaIdPorNombre = nombre => { const m = materiasRows.find(x => materiaNombre(x) === String(nombre)); return m ? m.id_materia : ''; };
const disponibilidad = $('Leer Disponibilidad').all().map(i => i.json);
const tutorias = $('Leer Tutorias').all().map(i => i.json).map(t => ({ ...t, materia: t.materia || materiaNombrePorId(t.id_materia), horario: t.horario || ((t.hora_inicio || '') + '-' + (t.hora_fin || '')) }));

const opt = (label, value) => ({ label, value: value === undefined ? label : value });

const MAIN_OPC = [ opt('📚 Solicitar tutoría'), opt('📅 Mis tutorías'), opt('❌ Cancelar tutoría'), opt('👤 Mi perfil') ];
const START_OPC = [ opt('📝 Registrarme'), opt('🔑 Iniciar sesión') ];
const CONFIRM_OPC = [ opt('✅ Confirmar'), opt('🔙 Cancelar') ];

const out = { chatId, reply: '', sesionPaso: paso, sesionDatos: datos, idEstudiante: s.id_estudiante || '', action: 'none', actionData: {} };
const setPaso = p => { out.sesionPaso = p; };

const say = (mensaje, opciones) => {
  if (opciones && opciones.length) {
    const listado = opciones.map((o, i) => (i + 1) + '. ' + o.label).join('\n');
    out.reply = mensaje + '\n\n' + listado + '\n\n✏️ Responde con el número de la opción.';
  } else {
    out.reply = mensaje;
  }
  out.sesionDatos = { ...out.sesionDatos, __opciones: (opciones && opciones.length) ? opciones : [] };
};

const opcionesPrevias = Array.isArray(datos.__opciones) ? datos.__opciones : [];
if (opcionesPrevias.length && /^\d+$/.test(String(text).trim())) {
  const idx = parseInt(String(text).trim(), 10) - 1;
  if (idx >= 0 && idx < opcionesPrevias.length) {
    text = opcionesPrevias[idx].value;
  }
}

const estudiantePorChat = () => estudiantes.find(e => String(e.telegram_id) === String(chatId));
const estudiantePorCedula = c => estudiantes.find(e => String(e.cedula).trim() === String(c).trim());
const nextId = (arr, campo, pref) => {
  let max = 0;
  for (const r of arr) {
    const m = String(r[campo] || '').match(/(\d+)$/);
    if (m) max = Math.max(max, parseInt(m[1], 10));
  }
  return pref + String(max + 1).padStart(3, '0');
};
const horasHasta = (fecha, horario) => {
  try {
    const parts = String(fecha).split('/');
    const d = new Date(parts[2] + '-' + parts[1].padStart(2,'0') + '-' + parts[0].padStart(2,'0') + 'T' + String(horario).split('-')[0].trim() + ':00');
    return (d.getTime() - Date.now()) / 3600000;
  } catch (e) { return 999; }
};
const diaSemana = fecha => {
  try {
    const parts = String(fecha).split('/');
    const d = new Date(parts[2] + '-' + parts[1].padStart(2,'0') + '-' + parts[0].padStart(2,'0') + 'T12:00:00');
    return ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'][d.getDay()];
  } catch (e) { return ''; }
};

const diasLargo = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
const mesesLargo = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const horaAmPm = (hhmm) => {
  const partes = String(hhmm).split(':');
  const hh = parseInt(partes[0], 10);
  const mm = partes[1] || '00';
  const periodo = hh >= 12 ? 'PM' : 'AM';
  let h12 = hh % 12; if (h12 === 0) h12 = 12;
  return h12 + ':' + mm + ' ' + periodo;
};
const fechaLarga = (d) => diasLargo[d.getDay()] + ' ' + d.getDate() + ' de ' + mesesLargo[d.getMonth()];
const fechaDeDia = (diaNombre) => {
  const ahora = new Date();
  const idx = diasLargo.findIndex(x => String(x).toLowerCase() === String(diaNombre).toLowerCase());
  if (idx < 0) return '';
  const hoy = ahora.getDay();
  let diff = idx - hoy;
  if (diff < 0) diff += 7;
  const d = new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate() + diff);
  return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();
};
const ESTADOS_OCUPAN = ['Solicitada','Asignada','En curso','Programada'];
const slotLabel = (sl) => {
  return sl.dia + ' — ' + horaAmPm(sl.hora_inicio) + ' - ' + horaAmPm(sl.hora_fin) + ' (' + sl.tutorNombre + ')';
};
const generarSlots = (materiaTxt) => {
  const tutoresMateria = tutores.filter(t => String(t.estado) === 'Activo' && String(t.materias || '').toLowerCase().includes(String(materiaTxt).toLowerCase()));
  if (tutoresMateria.length === 0) return [];
  const conteo = {};
  for (const t of tutorias) { if (ESTADOS_OCUPAN.concat(['Finalizada']).includes(String(t.estado))) { conteo[t.id_tutor] = (conteo[t.id_tutor] || 0) + 1; } }
  const candidatos = [];
  for (const tutor of tutoresMateria) {
    const bloques = disponibilidad.filter(x => String(x.id_tutor) === String(tutor.id_tutor) && String(x.estado || 'Disponible') === 'Disponible');
    for (const bloque of bloques) {
      const dia = String(bloque.dia_semana || bloque.dia || '');
      const hi = String(bloque.hora_inicio || '');
      const hf = String(bloque.hora_fin || '');
      if (!dia || !hi || !hf) continue;
      const ocupado = tutorias.some(t => String(t.id_tutor) === String(tutor.id_tutor) && diaSemana(t.fecha) === dia && String(t.hora_inicio || '').trim() === hi.trim() && ESTADOS_OCUPAN.includes(String(t.estado)));
      if (ocupado) continue;
      candidatos.push({ id_tutor: tutor.id_tutor, tutorNombre: tutor.nombre, dia, hora_inicio: hi, hora_fin: hf, carga: conteo[tutor.id_tutor] || 0 });
    }
  }
  candidatos.sort((a, b) => {
    const ia = ['Lunes','Martes','Miércoles','Jueves','Viernes'].indexOf(a.dia);
    const ib = ['Lunes','Martes','Miércoles','Jueves','Viernes'].indexOf(b.dia);
    if (ia !== ib) return ia - ib;
    if (a.hora_inicio !== b.hora_inicio) return a.hora_inicio.localeCompare(b.hora_inicio);
    return a.carga - b.carga;
  });
  return candidatos;
};

if (estudiantePorChat() && (paso.startsWith('reg_') || paso === 'login_cedula')) { paso = 'autenticado'; out.sesionPaso = 'autenticado'; }

if (text === '/start' || text === '🔙 Cancelar' || text === '🔙 Menú principal' || text === '/menu') {
  const est = estudiantePorChat();
  if (est) {
    out.idEstudiante = est.id_estudiante;
    setPaso('autenticado');
    say('🎓 TUTORBOT\n\nHola ' + est.nombre + ', ¿qué deseas hacer?', MAIN_OPC);
  } else {
    setPaso('');
    say('👋 ¡Bienvenido a TutorBot!\n\nPara comenzar elige una opción:', START_OPC);
  }
  out.action = 'saveSession';
  return [{ json: out }];
}

if (paso === '' || paso === undefined) {
  if (text === '📝 Registrarme') {
    setPaso('reg_nombre'); out.sesionDatos = {};
    say('📝 REGISTRO\n\nEscribe tu nombre completo (solo letras):');
  } else if (text === '🔑 Iniciar sesión') {
    setPaso('login_cedula');
    say('🔑 INICIAR SESIÓN\n\nIngresa tu número de cédula:');
  } else {
    say('👋 ¡Bienvenido a TutorBot!\n\nPara comenzar elige una opción:', START_OPC);
  }
  out.action = 'saveSession';
  return [{ json: out }];
}

if (paso === 'reg_nombre') {
  if (!/^[A-Za-zÁÉÍÓÚáéíóúÑñÜü\s]{3,80}$/.test(text)) {
    say('⚠️ Nombre inválido. Solo letras, espacios y acentos. Intenta de nuevo:');
  } else {
    datos.nombre = text; out.sesionDatos = datos; setPaso('reg_cedula');
    say('Gracias, ' + text + '.\n\nAhora ingresa tu número de cédula (6 a 10 dígitos):');
  }
  out.action = 'saveSession'; return [{ json: out }];
}
if (paso === 'reg_cedula') {
  if (!/^\d{6,10}$/.test(text)) {
    say('⚠️ Cédula inválida. Debe ser numérica de 6 a 10 dígitos. Intenta de nuevo:');
  } else if (estudiantePorCedula(text)) {
    setPaso(''); out.sesionDatos = {};
    say('🚫 Esa cédula ya está registrada. Puedes iniciar sesión:', START_OPC);
  } else {
    datos.cedula = text; out.sesionDatos = datos; setPaso('reg_correo');
    say('Ahora ingresa tu correo electrónico:');
  }
  out.action = 'saveSession'; return [{ json: out }];
}
if (paso === 'reg_correo') {
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text)) {
    say('⚠️ Correo inválido. Verifica el formato (sin espacios) e intenta de nuevo:');
  } else if (estudiantes.find(e => String(e.correo).toLowerCase() === text.toLowerCase())) {
    setPaso(''); out.sesionDatos = {};
    say('🚫 Ese correo ya está registrado. Puedes iniciar sesión:', START_OPC);
  } else {
    datos.correo = text; out.sesionDatos = datos; setPaso('reg_confirmar');
    say('📋 RESUMEN DE REGISTRO\n\n👤 Nombre: ' + datos.nombre + '\n🪪 Cédula: ' + datos.cedula + '\n📧 Correo: ' + datos.correo + '\n\n¿Confirmas tus datos?', CONFIRM_OPC);
  }
  out.action = 'saveSession'; return [{ json: out }];
}
if (paso === 'reg_confirmar') {
  if (text === '✅ Confirmar') {
    const idEst = nextId(estudiantes, 'id_estudiante', 'EST');
    out.action = 'registrarEstudiante';
    out.actionData = { id_estudiante: idEst, nombre: datos.nombre, cedula: datos.cedula, correo: datos.correo, telegram_id: chatId, estado: 'Activo' };
    out.idEstudiante = idEst;
    setPaso('autenticado'); out.sesionDatos = {};
    say('✅ ¡Registro exitoso! Tu ID es ' + idEst + '.\n\n🎓 TUTORBOT\n¿Qué deseas hacer?', MAIN_OPC);
  } else {
    setPaso(''); out.sesionDatos = {}; out.action = 'saveSession';
    say('Registro cancelado. Cuando quieras, elige una opción:', START_OPC);
  }
  return [{ json: out }];
}

if (paso === 'login_cedula') {
  const est = estudiantePorCedula(text);
  if (!est) {
    setPaso(''); out.action = 'saveSession';
    say('🔍 No encontramos esa cédula. ¿Deseas registrarte?', START_OPC);
  } else if (String(est.estado) !== 'Activo') {
    setPaso(''); out.action = 'saveSession';
    say('⚠️ Tu cuenta está Inactiva. Comunícate con coordinación académica.');
  } else {
    if (String(est.telegram_id) !== String(chatId)) {
      out.action = 'vincularTelegram';
      out.actionData = { id_estudiante: est.id_estudiante, nombre: est.nombre, cedula: est.cedula, correo: est.correo, telegram_id: chatId, estado: est.estado };
    } else {
      out.action = 'saveSession';
    }
    out.idEstudiante = est.id_estudiante;
    setPaso('autenticado'); out.sesionDatos = {};
    say('👋 Hola de nuevo, ' + est.nombre + '.\n\n🎓 TUTORBOT\n¿Qué deseas hacer?', MAIN_OPC);
  }
  return [{ json: out }];
}

if (text === '📚 Solicitar tutoría') {
  if (materias.length === 0) {
    say('⚠️ No hay materias configuradas. Comunícate con coordinación.');
    out.action = 'saveSession'; return [{ json: out }];
  }
  setPaso('sol_materia'); out.sesionDatos = {};
  const opciones = materias.map(m => opt(m));
  opciones.push(opt('🔙 Menú principal'));
  say('📚 SOLICITAR TUTORÍA\n\nElige la materia:', opciones);
  out.action = 'saveSession'; return [{ json: out }];
}
if (paso === 'sol_materia') {
  if (!materias.includes(text)) {
    const opciones = materias.map(m => opt(m)); opciones.push(opt('🔙 Menú principal'));
    say('⚠️ Opción no válida. Elige la materia:', opciones);
    out.action = 'saveSession'; return [{ json: out }];
  }
  datos.materia = text; out.sesionDatos = datos; setPaso('sol_motivo');
  const opciones = [opt('📖 Repasar un tema'), opt('❓ Resolver dudas'), opt('📝 Prepararme para un examen'), opt('💻 Ayuda con un proyecto'), opt('📚 Otro motivo'), opt('🔙 Menú principal')];
  say('Materia: ' + datos.materia + '\n\n¿Cuál es el motivo?', opciones);
  out.action = 'saveSession'; return [{ json: out }];
}
if (paso === 'sol_motivo') {
  const validos = ['📖 Repasar un tema','❓ Resolver dudas','📝 Prepararme para un examen','💻 Ayuda con un proyecto','📚 Otro motivo'];
  if (!validos.includes(text)) {
    const opciones = validos.map(v => opt(v)); opciones.push(opt('🔙 Menú principal'));
    say('⚠️ Opción no válida. ¿Cuál es el motivo?', opciones);
    out.action = 'saveSession'; return [{ json: out }];
  }
  datos.motivo = text; out.sesionDatos = datos; setPaso('sol_tema');
  say('Motivo: ' + datos.motivo + '\n\nEscribe el tema específico (ej: Estructuras de datos y listas enlazadas):');
  out.action = 'saveSession'; return [{ json: out }];
}
if (paso === 'sol_tema') {
  if (text.length < 3) { say('⚠️ Escribe un tema válido:'); out.action = 'saveSession'; return [{ json: out }]; }
  datos.tema = text; out.sesionDatos = datos;
  const slots = generarSlots(datos.materia);
  if (slots.length === 0) {
    setPaso('autenticado'); out.sesionDatos = {};
    say('😔 No hay horarios disponibles para ' + datos.materia + ' esta semana (lunes a viernes).\nIntenta la próxima semana o contacta a coordinación académica.', MAIN_OPC);
    out.action = 'saveSession'; return [{ json: out }];
  }
  setPaso('sol_slot');
  const opciones = slots.map(sl => opt(slotLabel(sl), JSON.stringify({ id_tutor: sl.id_tutor, dia: sl.dia, hora_inicio: sl.hora_inicio, hora_fin: sl.hora_fin })));
  opciones.push(opt('🔙 Menú principal'));
  say('📚 ' + datos.materia + '\n\nDisponibilidad del tutor esta semana (lunes a viernes). Selecciona el día y la hora:', opciones);
  out.action = 'saveSession'; return [{ json: out }];
}
if (paso === 'sol_slot') {
  let seleccion = null;
  try { seleccion = JSON.parse(text); } catch (e) { seleccion = null; }
  if (!seleccion || !seleccion.id_tutor || !seleccion.dia || !seleccion.hora_inicio || !seleccion.hora_fin) {
    const slots = generarSlots(datos.materia);
    if (slots.length === 0) {
      setPaso('autenticado'); out.sesionDatos = {};
      say('😔 Ya no hay horarios disponibles para ' + datos.materia + ' esta semana. Intenta más tarde.', MAIN_OPC);
      out.action = 'saveSession'; return [{ json: out }];
    }
    const opciones = slots.map(sl => opt(slotLabel(sl), JSON.stringify({ id_tutor: sl.id_tutor, dia: sl.dia, hora_inicio: sl.hora_inicio, hora_fin: sl.hora_fin })));
    opciones.push(opt('🔙 Menú principal'));
    say('⚠️ Opción no válida. Selecciona un día y hora disponibles:', opciones);
    out.action = 'saveSession'; return [{ json: out }];
  }
  const fechaSel = fechaDeDia(seleccion.dia);
  datos.id_tutor_slot = seleccion.id_tutor;
  datos.dia = seleccion.dia;
  datos.fecha = fechaSel;
  datos.hora_inicio = seleccion.hora_inicio;
  datos.hora_fin = seleccion.hora_fin;
  out.sesionDatos = datos;
  setPaso('sol_confirmar');
  const horaIniTxt = horaAmPm(seleccion.hora_inicio);
  const horaFinTxt = horaAmPm(seleccion.hora_fin);
  say('📋 RESUMEN DE TU SOLICITUD\n\n📚 Materia: ' + datos.materia + '\n📝 Motivo: ' + datos.motivo + '\n📌 Tema: ' + datos.tema + '\n📅 Día: ' + seleccion.dia + '\n🕙 Horario: ' + horaIniTxt + ' – ' + horaFinTxt + '\n\n¿Deseas enviar esta solicitud?', CONFIRM_OPC);
  out.action = 'saveSession'; return [{ json: out }];
}
if (paso === 'sol_confirmar') {
  if (text !== '✅ Confirmar') {
    setPaso('autenticado'); out.sesionDatos = {}; out.action = 'saveSession';
    say('Solicitud cancelada.\n\n🎓 TUTORBOT\n¿Qué deseas hacer?', MAIN_OPC);
    return [{ json: out }];
  }
  const est = estudiantePorChat();
  const idSol = nextId(tutorias, 'id_tutoria', 'SOL');
  const idMateria = materiaIdPorNombre(datos.materia);
  const ahora = $now.toISO();
  const tutorElegido = tutores.find(t => String(t.id_tutor) === String(datos.id_tutor_slot));
  const sigueLibre = !!tutorElegido && !tutorias.some(t => String(t.id_tutor) === String(datos.id_tutor_slot) && diaSemana(t.fecha) === datos.dia && String(t.hora_inicio || '').trim() === String(datos.hora_inicio).trim() && ESTADOS_OCUPAN.includes(String(t.estado)));

  if (sigueLibre) {
    out.action = 'crearTutoriaAsignada';
    out.actionData = {
      tutoria: { id_tutoria: idSol, id_estudiante: est.id_estudiante, id_tutor: tutorElegido.id_tutor, id_materia: idMateria, materia: datos.materia, motivo: datos.motivo, tema: datos.tema, fecha: datos.fecha, hora_inicio: datos.hora_inicio, hora_fin: datos.hora_fin, estado: 'Asignada', fecha_solicitud: ahora, fecha_asignacion: ahora },
      tutorChatId: String(tutorElegido.telegram_id || ''),
      tutorNombre: tutorElegido.nombre,
      estudianteNombre: est.nombre,
    };
    setPaso('autenticado'); out.sesionDatos = {};
    const horaIniTxt = horaAmPm(datos.hora_inicio);
    const horaFinTxt = horaAmPm(datos.hora_fin);
    say('✅ ¡Tutoría asignada!\n\n🟢 ' + datos.materia + '\n👩‍🏫 Tutor: ' + tutorElegido.nombre + '\n📅 ' + datos.dia + '\n🕙 ' + horaIniTxt + ' – ' + horaFinTxt + '\n📌 Estado: Asignada\n🆔 ' + idSol, MAIN_OPC);
  } else {
    out.action = 'crearTutoriaSolicitada';
    out.actionData = {
      tutoria: { id_tutoria: idSol, id_estudiante: est.id_estudiante, id_tutor: '', id_materia: idMateria, motivo: datos.motivo, tema: datos.tema, fecha: datos.fecha, hora_inicio: datos.hora_inicio, hora_fin: datos.hora_fin, estado: 'Solicitada', fecha_solicitud: ahora, fecha_asignacion: '' },
    };
    setPaso('autenticado'); out.sesionDatos = {};
    say('😔 Justo se ocupó ese horario mientras decidías. Tu solicitud quedó registrada como Solicitada (' + idSol + ') para que coordinación la reasigne.\n\nPuedes intentar solicitar otra tutoría desde el menú.', MAIN_OPC);
  }
  return [{ json: out }];
}

if (text === '📅 Mis tutorías') {
  const est = estudiantePorChat();
  const mias = tutorias.filter(t => String(t.id_estudiante) === String(est ? est.id_estudiante : '') && ['Solicitada','Asignada','En curso'].includes(String(t.estado)));
  if (mias.length === 0) {
    say('📅 No tienes tutorías activas por ahora.', MAIN_OPC);
  } else {
    let msg = '📅 MIS TUTORÍAS\n';
    for (const t of mias) {
      const tutor = tutores.find(x => String(x.id_tutor) === String(t.id_tutor));
      const icono = t.estado === 'Asignada' ? '🟢' : (t.estado === 'En curso' ? '🔵' : '🟡');
      msg += '\n' + icono + ' ' + t.materia + ' (' + t.id_tutoria + ')\n';
      msg += t.estado === 'Solicitada' ? '⏳ Buscando tutor...\n' : '👩‍🏫 ' + (tutor ? tutor.nombre : 'Por asignar') + '\n';
      msg += '📅 ' + t.fecha + '  🕙 ' + t.horario + '\n📌 ' + t.estado + '\n';
    }
    say(msg, MAIN_OPC);
  }
  out.action = 'saveSession'; return [{ json: out }];
}

